<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Kanban Board</title>
    <style>
        :root {
            --bg-color: #f4f7f9;
            --column-bg: #ebedf0;
            --card-bg: #ffffff;
            --text-main: #172b4d;
            --text-subtle: #5e6c84;
            --accent: #0052cc;
            --danger: #ef4444;
            --border-radius: 8px;
            --shadow: 0 2px 5px rgba(0,0,0,0.1);
        }

        * {
            box-sizing: border-box;
            margin: 0;
            padding: 0;
        }

        body {
            font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
            background-color: var(--bg-color);
            color: var(--text-main);
            line-height: 1.5;
            padding: 20px;
        }

        header {
            margin-bottom: 30px;
            text-align: center;
        }

        h1 {
            margin-bottom: 20px;
            font-weight: 700;
        }

        /* Controls Section */
        .controls {
            display: flex;
            justify-content: center;
            gap: 10px;
            margin-bottom: 30px;
        }

        #new-card {
            padding: 10px 15px;
            border: 2px solid #ddd;
            border-radius: var(--border-radius);
            width: 300px;
            font-size: 16px;
            outline: none;
            transition: border-color 0.2s;
        }

        #new-card:focus {
            border-color: var(--accent);
        }

        #add-card {
            padding: 10px 20px;
            background-color: var(--accent);
            color: white;
            border: none;
            border-radius: var(--border-radius);
            font-weight: 600;
            cursor: pointer;
            transition: opacity 0.2s;
        }

        #add-card:hover {
            opacity: 0.9;
        }

        /* Board Layout */
        .board {
            display: flex;
            justify-content: center;
            align-items: flex-start;
            gap: 20px;
            flex-wrap: wrap;
        }

        .column {
            background-color: var(--column-bg);
            width: 350px;
            min-height: 400px;
            border-radius: var(--border-radius);
            display: flex;
            flex-direction: column;
            padding: 10px;
            transition: background-color 0.2s;
        }

        .column.drag-over {
            background-color: #dfe1e6;
            outline: 2px dashed var(--accent);
        }

        .column-header {
            padding: 10px;
            display: flex;
            justify-content: space-between;
            align-items: center;
        }

        .column-header h2 {
            font-size: 1rem;
            text-transform: uppercase;
            letter-spacing: 0.05em;
            color: var(--text-subtle);
        }

        .count {
            background: #d0d4db;
            padding: 2px 8px;
            border-radius: 12px;
            font-size: 0.85rem;
            font-weight: bold;
            color: var(--text-main);
        }

        .card-container {
            flex-grow: 1;
            min-height: 50px;
        }

        /* Card Styling */
        .card {
            background-color: var(--card-bg);
            padding: 15px;
            margin-bottom: 10px;
            border-radius: var(--border-radius);
            box-shadow: var(--shadow);
            cursor: grab;
            display: flex;
            justify-content: space-between;
            align-items: center;
            word-break: break-word;
            transition: transform 0.1s, box-shadow 0.1s;
        }

        .card:active {
            cursor: grabbing;
        }

        .card:hover {
            box-shadow: 0 4px 8px rgba(0,0,0,0.15);
        }

        .card-text {
            flex-grow: 1;
            padding-right: 10px;
            font-size: 0.95rem;
        }

        .card-del {
            background: none;
            border: none;
            color: var(--text-subtle);
            cursor: pointer;
            font-size: 1.2rem;
            line-height: 1;
            padding: 0 5px;
            transition: color 0.2s;
        }

        .card-del:hover {
            color: var(--danger);
        }

        /* Utilities */
        @media (max-width: 768px) {
            .board {
                flex-direction: column;
                align-items: center;
            }
            .column {
                width: 100%;
                max-width: 400px;
            }
        }
    </style>
</head>
<body>

    <header>
        <h1>Kanban Board</h1>
    </header>

    <div class="controls">
        <input type="text" id="new-card" placeholder="Enter task description..." autocomplete="off">
        <button id="add-card">Add Task</button>
    </div>

    <div class="board">
        <!-- TODO COLUMN -->
        <div class="column" id="col-todo">
            <div class="column-header">
                <h2>To Do</h2>
                <span class="count">0</span>
            </div>
            <div class="card-container" ondragover="handleDragOver(event)" ondrop="handleDrop(event, 'col-todo')" ondragleave="handleDragLeave(event)">
                <!-- Cards go here -->
            </div>
        </div>

        <!-- DOING COLUMN -->
        <div class="column" id="col-doing">
            <div class="column-header">
                <h2>Doing</h2>
                <span class="count">0</span>
            </div>
            <div class="card-container" ondragover="handleDragOver(event)" ondrop="handleDrop(event, 'col-doing')" ondragleave="handleDragLeave(event)">
                <!-- Cards go here -->
            </div>
        </div>

        <!-- DONE COLUMN -->
        <div class="column" id="col-done">
            <div class="column-header">
                <h2>Done</h2>
                <span class="count">0</span>
            </div>
            <div class="card-container" ondragover="handleDragOver(event)" ondrop="handleDrop(event, 'col-done')" ondragleave="handleDragLeave(event)">
                <!-- Cards go here -->
            </div>
        </div>
    </div>

    <script>
        /**
         * APP STATE & PERSISTENCE
         */
        let state = {
            cards: [] // Array of { id: string, text: string, colId: string }
        };

        const STORAGE_KEY = 'kanban_board_data';

        function saveToLocalStorage() {
            localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
        }

        function loadFromLocalStorage() {
            const saved = localStorage.item ? localStorage.getItem(STORAGE_KEY) : null;
            if (saved) {
                try {
                    state = JSON.parse(saved);
                } catch (e) {
                    console.error("Failed to parse storage", e);
                }
            }
        }

        /**
         * DOM ELEMENTS
         */
        const inputEl = document.getElementById('new-card');
        const addBtn = document.getElementById('add-card');
        const columns = ['col-todo', 'col-doing', 'col-done'];

        /**
         * CORE LOGIC
         */

        function init() {
            loadFromLocalStorage();
            renderAll();

            // Event Listeners
            addBtn.addEventListener('click', createNewCard);
            inputEl.addEventListener('keypress', (e) => {
                if (e.key === 'Enter') createNewCard();
            });
        }

        function renderAll() {
            // Clear all containers first
            columns.forEach(colId => {
                const container = document.querySelector(`#${colId} .card-container`);
                container.innerHTML = '';
                updateColumnCount(colId);
            });

            // Render cards from state
            state.cards.forEach(cardData => {
                const cardEl = createCardElement(cardData);
                const container = document.querySelector(`#${cardData.colId} .card-container`);
                if (container) container.appendChild(cardEl);
            });

            updateAllCounts();
        }

        function createNewCard() {
            const text = inputEl.value.trim();
            if (!text) return;

            const newCard = {
                id: Date.now().toString(),
                text: text,
                colId: 'col-todo'
            };

            state.cards.push(newCard);
            saveToLocalStorage();

            const cardEl = createCardElement(newCard);
            document.querySelector('#col-todo .card-container').appendChild(cardEl);

            inputEl.value = '';
            updateAllCounts();
        }

        function createCardElement(cardData) {
            const div = document.createElement('div');
            div.className = 'card';
            div.id = `card-${cardData.id}`;
            div.draggable = true;
            div.dataset.id = cardData.id;

            // Drag Start handler
            div.addEventListener('dragstart', (e) => {
                e.dataTransfer.setData('text/plain', cardData.id);
                // Small delay to allow the drag image to be captured before opacity changes
                setTimeout(() => div.style.opacity = '0.5', 0);
            });

            div.addEventListener('dragend', (e) => {
                div.style.opacity = '1';
            });

            const textSpan = document.createElement('span');
            textSpan.className = 'card-text';
            textSpan.textContent = cardData.text;

            const delBtn = document.createElement('button');
            delBtn.className = 'card-del';
            delBtn.innerHTML = '&times;';
            delBtn.title = "Delete Card";
            delBtn.onclick = () => deleteCard(cardData.id);

            div.appendChild(textSpan);
            div.appendChild(delBtn);
            return div;
        }

        function deleteCard(id) {
            state.cards = state.cards.filter(c => c.id !== id);
            saveToLocalStorage();
            renderAll();
        }

        /**
         * DRAG AND DROP HANDLERS
         */

        function handleDragOver(e) {
            e.preventDefault(); // Required to allow drop
            const container = e.currentTarget;
            // Visual cue: find the parent column and add class
            container.closest('.column').classList.add('drag-over');
        }

        function handleDragLeave(e) {
            const container = e.currentTarget;
            container.closest('.column').classList.remove('drag-over');
        }

        function handleDrop(e, targetColId) {
            e.preventDefault();
            const cardId = e.dataTransfer.getData('text/plain');
            const columnEl = document.getElementById(targetColId);
            columnEl.classList.remove('drag-over');

            // Update the state
            const cardIndex = state.cards.findIndex(c => c.id === cardId);
            if (cardIndex !== -1 && state.cards[cardIndex].colId !== targetColId) {
                state.cards[cardIndex].colId = targetColId;
                saveToLocalStorage();
                renderAll(); // Re-rendering ensures counts and DOM are perfectly in sync
            }
        }

        /**
         * UI UPDATES
         */

        function updateColumnCount(colId) {
            const col = document.getElementById(colId);
            if (!col) return;
            const countSpan = col.querySelector('.count');
            const cardCount = col.querySelectorAll('.card').length;
            countSpan.textContent = cardCount;
        }

        function updateAllCounts() {
            columns.forEach(id => updateColumnCount(id));
        }

        // Initialize the app
        init();

    </script>
</body>
</html>
